/* [hidden] rule for safety, though not used */
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  background: #1e293b;
  color: #e2e8f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.card {
  background: #0f172a;
  border-radius: 24px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
  padding: 32px 24px;
  max-width: 700px;
  width: 100%;
  border: 1px solid #334155;
}

h1 {
  font-size: 2rem;
  font-weight: 600;
  margin-bottom: 8px;
  color: #f1f5f9;
  letter-spacing: -0.02em;
}

.subtitle {
  color: #94a3b8;
  margin-bottom: 24px;
  font-size: 1rem;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  margin-bottom: 24px;
}

.inputs label {
  display: flex;
  flex-direction: column;
  align-items: center;
  font-size: 0.9rem;
  font-weight: 500;
  color: #cbd5e1;
  gap: 4px;
}

.inputs input {
  width: 100%;
  padding: 10px 4px;
  font-size: 1rem;
  text-align: center;
  border: 2px solid #334155;
  border-radius: 8px;
  background: #1e293b;
  color: #f1f5f9;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.inputs input:hover {
  border-color: #475569;
}

.inputs input:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.3);
}

.inputs input:active {
  border-color: #0ea5e9;
}

.chart-container {
  background: #1e293b;
  border-radius: 16px;
  padding: 16px;
  margin-bottom: 24px;
  border: 1px solid #334155;
}

canvas {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
}

.average {
  font-size: 1.25rem;
  font-weight: 600;
  color: #f1f5f9;
  text-align: center;
  background: #1e293b;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid #334155;
}

/* Responsive */
@media (max-width: 500px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.75rem;
  }
  .inputs {
    grid-template-columns: repeat(4, 1fr);
  }
  .inputs label {
    font-size: 0.8rem;
  }
  .inputs input {
    font-size: 0.9rem;
    padding: 8px 2px;
  }
}

@media (max-width: 360px) {
  .inputs {
    grid-template-columns: repeat(3, 1fr);
  }
}

const days = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const inputs = days.map(id => document.getElementById(id));
const canvas = document.getElementById('chart');
const ctx = canvas.getContext('2d');
const averageEl = document.getElementById('average');

function getValues() {
  return inputs.map(input => {
    let val = parseFloat(input.value);
    if (isNaN(val) || val < 0) val = 0;
    if (val > 12) val = 12;
    return val;
  });
}

function drawChart(values) {
  const w = canvas.width;
  const h = canvas.height;
  const padding = { top: 20, right: 20, bottom: 40, left: 40 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;
  const maxVal = 12;
  const barWidth = chartW / values.length * 0.7;
  const gap = chartW / values.length * 0.3;

  ctx.clearRect(0, 0, w, h);

  // Background grid lines
  ctx.strokeStyle = '#334155';
  ctx.lineWidth = 1;
  for (let i = 0; i <= maxVal; i += 2) {
    const y = padding.top + chartH - (i / maxVal) * chartH;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillStyle = '#94a3b8';
    ctx.font = '12px system-ui, sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(i, padding.left - 8, y);
  }

  // Find max index for highlighting
  let maxIndex = 0;
  for (let i = 1; i < values.length; i++) {
    if (values[i] > values[maxIndex]) maxIndex = i;
  }

  // Draw bars
  values.forEach((val, i) => {
    const x = padding.left + i * (chartW / values.length) + gap / 2;
    const barH = (val / maxVal) * chartH;
    const y = padding.top + chartH - barH;

    // Bar color: highlight max
    if (i === maxIndex && val > 0) {
      ctx.fillStyle = '#38bdf8'; // highlight color
    } else {
      ctx.fillStyle = '#64748b';
    }

    // Rounded bars
    const radius = Math.min(6, barWidth / 2);
    ctx.beginPath();
    ctx.moveTo(x + radius, y);
    ctx.lineTo(x + barWidth - radius, y);
    ctx.quadraticCurveTo(x + barWidth, y, x + barWidth, y + radius);
    ctx.lineTo(x + barWidth, padding.top + chartH);
    ctx.lineTo(x, padding.top + chartH);
    ctx.lineTo(x, y + radius);
    ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
    ctx.fill();

    // Day label
    ctx.fillStyle = '#cbd5e1';
    ctx.font = '14px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(dayNames[i], x + barWidth / 2, padding.top + chartH + 8);

    // Value label on top of bar
    if (val > 0) {
      ctx.fillStyle = '#f1f5f9';
      ctx.font = 'bold 14px system-ui, sans-serif';
      ctx.textBaseline = 'bottom';
      ctx.fillText(val, x + barWidth / 2, y - 4);
    }
  });
}

function update() {
  const values = getValues();
  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / 7;
  averageEl.textContent = `Weekly average: ${avg.toFixed(1)} hours`;
  drawChart(values);
}

inputs.forEach(input => {
  input.addEventListener('input', () => {
    let val = parseFloat(input.value);
    if (!isNaN(val)) {
      if (val < 0) input.value = 0;
      if (val > 12) input.value = 12;
    }
    update();
  });
});

// Initial draw
update();
